import sys
f=sys.argv[1]; s=open(f,encoding='utf-8').read()
def sub(a,b,n=1):
    global s; assert s.count(a)==n,(a[:90],s.count(a)); s=s.replace(a,b)
# ---- day 1 ----
sub("await say(['ผมตื่นก่อนแตรปลุกมาหกสิบแปดปี\\nทุกวันนี้ไม่มีแตรแล้ว ผมก็ยังตื่นก่อนมันอยู่ดี','ร่างกายจำคำสั่งได้นาน\\nนานกว่าคนที่เคยออกคำสั่งจะอยู่ให้เชื่อฟัง']);",
    "await say(['ผมตื่นก่อนแตรปลุกมาหกสิบแปดปี\\nทุกวันนี้ไม่มีแตรแล้ว ผมก็ยังตื่นก่อนมันอยู่ดี']);")
sub("await say(['…สาม','เมื่อก่อนผมนับถึงสาม ให้ทั้งกองร้อยลุกพร้อมกัน\\nเดี๋ยวนี้ผมนับให้เข่าสองข้างของตัวเอง','เจ้าดำนั่งรออยู่แล้ว\\nสิบสี่ปี มันไม่เคยตื่นหลังผมเลยสักวัน','หมาแก่กับทหารแก่\\nแข่งกันตื่นเช้า โดยไม่มีใครต้องไปไหน']);",
    "await say(['…สาม\\nเมื่อก่อนผมนับถึงสามให้ทั้งกองร้อย เดี๋ยวนี้นับให้เข่าสองข้างของตัวเอง','เจ้าดำนั่งรออยู่แล้ว\\nหมาแก่กับทหารแก่ แข่งกันตื่นเช้า โดยไม่มีใครต้องไปไหน']);")
sub("await say(first?['ผมวางมือลงบนหัวมัน\\nมันหลับตา เหมือนรอสิ่งนี้มาทั้งคืน','หมออธิบายว่าหมาอายุเท่านี้\\nหนึ่งวันของมัน ยาวเท่าหนึ่งสัปดาห์ของคน','ผมเลยพยายามไม่ให้มันต้องรอนาน']",
    "await say(first?['ผมวางมือลงบนหัวมัน มันหลับตา\\nหมาอายุสิบสี่ หนึ่งวันของมันยาวเท่าหนึ่งสัปดาห์ของคน ผมเลยไม่อยากให้มันรอนาน']")
sub("['รูปแต่งงาน ปีสองพันห้า\\nผมเจ็ดสิบสอง อาเหมยยี่สิบสี่','คนในหมู่บ้านนินทาว่าเธอแต่งกับเงินบำนาญ\\nปีแรกๆ ผมเองก็แอบคิดแบบนั้น','จนปีที่ผมเป็นปอดบวม เธอนั่งเฝ้าที่โรงพยาบาลสามคืน\\nเงินบำนาญไม่เคยนั่งเฝ้าใคร','ผมไม่มีรูปแม่สักใบ\\nหน้าแม่ในหัวผม จางลงปีละนิด เหมือนรูปที่โดนแดด']",
    "['รูปแต่งงาน ปีสองพันห้า ผมเจ็ดสิบสอง อาเหมยยี่สิบสี่\\nคนในหมู่บ้านนินทาว่าเธอแต่งกับเงินบำนาญ แต่เงินบำนาญไม่เคยนั่งเฝ้าผมที่โรงพยาบาลสามคืน','ผมไม่มีรูปแม่สักใบ\\nหน้าแม่ในหัวผม จางลงปีละนิด เหมือนรูปที่โดนแดด']")
sub("await say(['ปฏิทินของผมไม่มีสัปดาห์ไหนว่าง\\nสัปดาห์ละสองสามวงแดง โรงพยาบาลใหญ่ คลินิกผิวหนัง คลินิกหมออู๋ คลินิกหัวมุม','ผมวงเองทุกวง ด้วยปากกาแดง\\nคนที่มีนัด คือคนที่ยังมีที่ให้ไป','มีวงสีน้ำเงินด้วย ลายมืออาเหมย\\nวันที่เธอได้กลับบ้าน สัปดาห์ละสองวง ผมนับวงน้ำเงินบ่อยกว่าวงแดง']);",
    "await say(['วงแดงสัปดาห์ละสองสามวง ผมวงเอง โรงพยาบาลใหญ่ คลินิกผิวหนัง คลินิกหัวมุม\\nคนที่มีนัด คือคนที่ยังมีที่ให้ไป','วงน้ำเงินเป็นลายมืออาเหมย วันที่เธอได้กลับบ้าน\\nผมนับวงน้ำเงินบ่อยกว่าวงแดง']);")
sub("['รองเท้าแตะคู่เล็กข้างประตู หันปลายเข้าห้อง\\nของอาเหมย เธอถอดไว้แบบนี้ทุกครั้งที่กลับจากเวร','สัปดาห์หนึ่ง มันได้ใส่สองสามวัน\\nวันที่เหลือ มันรออยู่ตรงนี้ เหมือนผม','ผ้ากันเปื้อนบนตะปู ยังมีแป้งติดอยู่จุดหนึ่ง\\nจากเกี๊ยวที่เธอห่อเมื่อวันอาทิตย์']",
    "['รองเท้าแตะคู่เล็กของอาเหมย หันปลายเข้าห้อง\\nสัปดาห์หนึ่งมันได้ใส่สองสามวัน วันที่เหลือ มันรออยู่ตรงนี้ เหมือนผม']")
sub("['ชั้นสี่ สูงพอจะมองเห็นหลังคาตลาด\\nและสูงเกินกว่าผมจะลงไปถึงมัน','รถน้ำเต้าหู้มาแล้วก็ไป\\nผมจำเสียงกระดิ่งได้ แต่จำรสไม่ได้แล้ว']",
    "['ชั้นสี่ สูงพอจะมองเห็นหลังคาตลาด และสูงเกินกว่าผมจะลงไปถึง\\nรถน้ำเต้าหู้มาแล้วก็ไป ผมจำเสียงกระดิ่งได้ แต่จำรสไม่ได้แล้ว']")
sub("['ตอนเช้ามีแต่ข่าว\\nข่าวของโลกที่เดินเร็วกว่าผมสามเท่า','เพลงเก่ามาตอนสี่โมงเย็น\\nคนแก่มีนัดอยู่ไม่กี่อย่าง นัดนี้ผมไม่เคยผิด']",
    "['ตอนเช้ามีแต่ข่าว เพลงเก่ามาตอนสี่โมงเย็น\\nคนแก่มีนัดอยู่ไม่กี่อย่าง นัดนี้ผมไม่เคยผิด']")
sub("await say(['กล่องยาเจ็ดช่อง เจ็ดวัน\\nอาเหมยจัดให้ทุกวันหยุดของเธอ นิ้วเธอเร็วเหมือนคนนับธนบัตร','อังคาร – เช้า เจ็ดเม็ด\\nผมไม่รู้ว่าเม็ดไหนรักษาอะไร อาเหมยรู้แทนผม เธอจัดยาให้คนแก่ที่บ้านพักวันละสามสิบคน รวมผมเป็นสามสิบเอ็ด','ครบ\\nวันนี้ไม่ต้องมีใครสั่ง']);",
    "await say(['กล่องยาเจ็ดช่อง อาเหมยจัดให้ทุกวันหยุดของเธอ\\nอังคาร – เช้า เจ็ดเม็ด ผมไม่รู้ว่าเม็ดไหนรักษาอะไร อาเหมยรู้แทนผม','ครบ\\nวันนี้ไม่ต้องมีใครสั่ง']);")
sub("await say(['อาเหมยเป็นภรรยาผม อายุสี่สิบเอ็ด\\nเธอทำงานเป็นกะที่บ้านพักทหารผ่านศึกกังซาน สัปดาห์หนึ่งได้กลับบ้านสองสามวัน','วันที่ไม่ได้กลับ เธอดูแลคนแก่ของคนอื่นทั้งวัน\\nแล้วโทรมาดูแลคนแก่ของตัวเอง เจ็ดโมงตรง','\"เหล่าหลี่ กินยาเช้าหรือยังคะ\"\\nเธอเรียกผมเหมือนเรียกเพื่อนรุ่นเดียวกัน ทั้งที่ผมแก่กว่าพ่อเธอ','ผมรับสายตอนกริ่งที่สองเสมอ\\nกริ่งแรก เอาไว้ให้ดูเหมือนผมกำลังยุ่งอยู่']);",
    "await say(['อาเหมยเป็นภรรยาผม อายุสี่สิบเอ็ด ทำงานเป็นกะที่บ้านพักทหารผ่านศึกกังซาน\\nสัปดาห์หนึ่งได้กลับบ้านสองสามวัน วันที่เหลือ เธอโทรมาตอนเจ็ดโมงตรง','\"เหล่าหลี่ กินยาเช้าหรือยังคะ\"\\nเธอเรียกผมเหมือนเพื่อนรุ่นเดียวกัน ทั้งที่ผมแก่กว่าพ่อเธอ','ผมรับสายตอนกริ่งที่สองเสมอ\\nกริ่งแรก เอาไว้ให้ดูเหมือนผมกำลังยุ่งอยู่']);")
sub("const T=[['07:00','…'],['07:06','กริ่งแรกยังไม่มา'],['07:15','นาฬิกาเดินดังกว่าทุกวัน'],['07:30','ผมยกหูขึ้นฟัง มีสัญญาณ\\nโทรศัพท์ไม่ได้เสีย']];",
    "const T=[['07:00','…'],['07:15','นาฬิกาเดินดังกว่าทุกวัน'],['07:30','ผมยกหูขึ้นฟัง มีสัญญาณ\\nโทรศัพท์ไม่ได้เสีย']];")
sub("await say(['วันอังคาร\\nเธอเข้าเวรดึก เพิ่งได้หลับเมื่อเช้านี้เอง','ดีแล้ว เธอควรได้นอน','ผมวางหูลงเบาๆ\\nเหมือนกลัวจะปลุกใคร']);",
    "await say(['วันอังคาร เธอเพิ่งออกเวรดึก เพิ่งได้หลับ\\nดีแล้ว เธอควรได้นอน','ผมวางหูลงเบาๆ\\nเหมือนกลัวจะปลุกใคร']);")
sub("await say(['ข้าวต้มหม้อนี้ ผมต้มไว้ตั้งแต่วันอาทิตย์\\nต้มครั้งเดียว กินสี่วัน เป็นยุทธวิธีประหยัดแก๊ส และประหยัดเข่า','เปิดฝา\\nมีกลิ่นเปรี้ยวบางๆ ลอยขึ้นมา เหมือนคำเตือนที่พูดเบาเกินไป']);",
    "await say(['ข้าวต้มหม้อนี้ต้มไว้ตั้งแต่วันอาทิตย์ ต้มครั้งเดียว กินสี่วัน ประหยัดแก๊ส ประหยัดเข่า\\nเปิดฝา มีกลิ่นเปรี้ยวบางๆ เหมือนคำเตือนที่พูดเบาเกินไป']);")
sub("await say(['ผมต้มจนเดือดพล่าน\\nความร้อนฆ่าได้ทุกอย่าง ครูฝึกเคยสอนไว้','กินไปครึ่งชาม\\nอีกครึ่ง เก็บไว้ให้ตัวเองตอนเย็น']);",
    "await say(['ผมต้มจนเดือดพล่าน ความร้อนฆ่าได้ทุกอย่าง ครูฝึกเคยสอนไว้\\nกินไปครึ่งชาม อีกครึ่งเก็บไว้ตอนเย็น']);")
sub("await say(['สี่ชั้นขาลง ผมพักสองครั้ง\\nสี่ชั้นขาขึ้น ผมเลิกนับ','แม่ค้าถามว่า \"ลุงหายไปไหนมาตั้งนาน\"\\nผมบอกว่า ช่วงนี้ยุ่ง','ข้าวต้มร้อนอยู่ในมือ แต่ผมต้องนั่งอีกครึ่งชั่วโมง\\nกว่ามือจะนิ่งพอถือช้อน','เจ้าดำได้ไข่เค็มไปครึ่งซีก\\nมันคิดว่าวันนี้เป็นวันพิเศษ']);",
    "await say(['สี่ชั้นขาลง ผมพักสองครั้ง สี่ชั้นขาขึ้น ผมเลิกนับ\\nแม่ค้าถามว่า \"ลุงหายไปไหนมาตั้งนาน\" ผมบอกว่า ช่วงนี้ยุ่ง','เจ้าดำได้ไข่เค็มไปครึ่งซีก\\nมันคิดว่าวันนี้เป็นวันพิเศษ']);")
sub("await say(['ห้องน้ำอยู่สุดทางเดิน ใช้ร่วมกันทั้งชั้น','ยี่สิบสามก้าว\\nผมวัดไว้ตั้งแต่ปีที่ยังไม่จำเป็นต้องวัด']);",
    "await say(['ห้องน้ำรวมอยู่สุดทางเดิน ยี่สิบสามก้าว\\nผมวัดไว้ตั้งแต่ปีที่ยังไม่จำเป็นต้องวัด']);")
sub("if(r.coughs) { energy(-1); await say(['ถึง','ผมเกาะขอบประตู\\nรอให้หน้าอกกลับมาเป็นของตัวเอง', r.coughs>1?'เด็กหนุ่มห้องสี่ศูนย์หกเดินสวนไป เขาพยักหน้าให้ผม\\nสี่วินาที ผมนับให้เขา':'ยี่สิบสามก้าวเท่าเดิม\\nแต่ทุกปี มันยาวขึ้นปีละนิด']); }",
    "if(r.coughs) { energy(-1); await say(['ถึง ผมเกาะขอบประตู รอให้หน้าอกกลับมาเป็นของตัวเอง\\nยี่สิบสามก้าวเท่าเดิม แต่ทุกปี มันยาวขึ้นปีละนิด']); }")
sub("else await say(['ถึง\\nเดินช้าก็ถึง ทหารราบรู้เรื่องนี้ดี','ปัญหามีอย่างเดียว\\nขากลับก็ยี่สิบสามก้าว']);",
    "else await say(['ถึง เดินช้าก็ถึง ทหารราบรู้เรื่องนี้ดี\\nปัญหามีอย่างเดียว ขากลับก็ยี่สิบสามก้าว']);")
sub("await say(['กลับถึงเตียง\\nมีอะไรหนักๆ นั่งทับหน้าอกผมอยู่ มันมาบ่อยจนผมเกือบจะตั้งชื่อให้','บนชั้นมียาพ่นสองอัน\\nหมออธิบายแล้วว่าอันไหนใช้ตอนไหน ผมพยักหน้า หมอก็พอใจ']);",
    "await say(['กลับถึงเตียง มีอะไรหนักๆ นั่งทับหน้าอก\\nบนชั้นมียาพ่นสองอัน หมออธิบายแล้วว่าอันไหนใช้ตอนไหน ผมพยักหน้า หมอก็พอใจ']);")
sub("if(c===1){ await say(['กด\\n…ไม่มีอะไรเกิดขึ้น นอกจากรสขมที่โคนลิ้น','ยาที่ไม่ทำให้รู้สึกอะไรเลย\\nจะให้เชื่อได้อย่างไรว่ามันกำลังทำงาน']);",
    "if(c===1){ await say(['กด… ไม่มีอะไรเกิดขึ้น นอกจากรสขมที่โคนลิ้น\\nยาที่ไม่ทำให้รู้สึกอะไรเลย จะให้เชื่อได้อย่างไรว่ามันทำงาน']);")
sub("await say(['ลมกลับเข้ามาในอก\\nเหมือนมีใครเปิดหน้าต่างให้','อันสีฟ้าไม่เคยทรยศผม\\nผมเลยเรียกใช้มันทุกวัน วันละหลายครั้ง','อันสีเขียวตั้งอยู่ข้างกัน เกือบเต็มหลอด\\nเหมือนทหารใหม่ที่ไม่มีใครไว้ใจให้ออกรบ']); cardOff();",
    "await say(['ลมกลับเข้ามาในอก อันสีฟ้าไม่เคยทรยศผม ผมเลยใช้มันวันละหลายครั้ง\\nอันสีเขียวเกือบเต็มหลอด เหมือนทหารใหม่ที่ไม่มีใครไว้ใจให้ออกรบ']); cardOff();")
sub("await say(['บ่ายโมง สามสิบสามองศา\\nพัดลมทำได้แค่ย้ายความร้อน จากมุมหนึ่งไปอีกมุมหนึ่ง','รีโมตแอร์อยู่ในลิ้นชัก ใต้บิลค่าไฟเดือนสิงหาปีก่อน\\nผมเก็บบิลใบนั้นไว้ เหมือนเก็บหมายเรียก']);",
    "await say(['บ่ายโมง สามสิบสามองศา พัดลมทำได้แค่ย้ายความร้อนไปมา\\nรีโมตแอร์อยู่ใต้บิลค่าไฟเดือนสิงหาปีก่อน ผมเก็บบิลใบนั้นไว้ เหมือนเก็บหมายเรียก']);")
sub("await say(['ลมเย็นแตะต้นคอ\\nผมรู้สึกผิดอยู่สามนาที แล้วก็หลับ','ตื่นมา เจ้าดำนอนหงายอยู่ใต้แอร์ สี่ขาชี้ฟ้า\\nอย่างน้อยในห้องนี้ ก็มีหนึ่งชีวิตที่ไม่คิดเรื่องเงิน']);",
    "await say(['ลมเย็นแตะต้นคอ ผมรู้สึกผิดอยู่สามนาที แล้วก็หลับ\\nตื่นมา เจ้าดำนอนหงายสี่ขาชี้ฟ้า อย่างน้อยในห้องนี้ ก็มีหนึ่งชีวิตที่ไม่คิดเรื่องเงิน']);")
