sub("await say(['…เพลงนี้','เพลงพื้นบ้านซานตง\\nแม่ร้องเพลงนี้ทุกตรุษจีน ผูกผ้าแดงที่เอว แล้วเต้นยางเกอในลานบ้านที่ชิงเต่า','ตรุษจีนปีหนึ่งเก้าสี่แปด แม่กวักมือเรียกผมเข้าไปเต้นด้วย\\nผมบอกว่า ผมโตแล้ว ไม่เต้นแบบเด็กๆ','ผมอายุสิบห้า\\nสามเดือนต่อมา ทหารมาที่หมู่บ้าน ผมได้โตจริงๆ ในวันเดียว','เพลงนี้ยาวสามนาทีสิบวินาที\\nผมมีเวลาทั้งชีวิต แต่ไม่ได้ให้แม่สามนาทีนั้น']);",
    "await say(['…เพลงนี้\\nเพลงพื้นบ้านซานตง แม่ผูกผ้าแดงที่เอว เต้นยางเกอในลานบ้านที่ชิงเต่าทุกตรุษจีน','ตรุษจีนปีหนึ่งเก้าสี่แปด แม่กวักมือเรียกผม\\nผมบอกว่า ผมสิบห้าแล้ว โตแล้ว ไม่เต้นแบบเด็กๆ','สามเดือนต่อมา ทหารมาที่หมู่บ้าน ผมได้โตจริงๆ ในวันเดียว\\nเพลงนี้ยาวสามนาทีสิบวินาที ผมมีเวลาทั้งชีวิต แต่ไม่ได้ให้แม่สามนาทีนั้น']);")
sub("await say(['เจ้าดำคาบสายจูงมาวางบนหลังเท้าผม แล้วนั่งลง\\nมันไม่เห่า ไม่ขูดประตู แค่มอง','หมาที่ไม่เคยเร่ง\\nเป็นหมาที่ปฏิเสธยากที่สุด']);",
    "await say(['เจ้าดำคาบสายจูงมาวางบนหลังเท้าผม แล้วนั่งมอง\\nหมาที่ไม่เคยเร่ง เป็นหมาที่ปฏิเสธยากที่สุด']);")
sub("await say(['สิบเอ็ดขั้น','ราวบันไดเย็นเฉียบ โลกหมุนช้าๆ รอบตัวผม','เจ้าดำลงไปถึงชานพักแล้ว มันหันกลับมามอง\\nแล้วเดินขึ้นมาทีละขั้น มานั่งลงข้างรองเท้าผม','สิบสี่ปี มันไม่เคยดึงสายจูงเลยสักครั้ง\\nผมเพิ่งเข้าใจวันนี้เอง มันไม่ได้เชื่อง มันรอ']);",
    "await say(['สิบเอ็ดขั้น ราวบันไดเย็นเฉียบ โลกหมุนช้าๆ รอบตัว\\nเจ้าดำเดินขึ้นมาทีละขั้น มานั่งข้างรองเท้าผม','สิบสี่ปี มันไม่เคยดึงสายจูงเลยสักครั้ง\\nผมเพิ่งเข้าใจวันนี้ มันไม่ได้เชื่อง มันรอ']);")
sub("else { await say(['มันวางคางลงบนรองเท้าผม ถอนหายใจยาวหนึ่งครั้ง\\nมันไม่ได้โกรธ','ผมอยากให้มันโกรธบ้าง']);",
    "else { await say(['มันวางคางลงบนรองเท้าผม ถอนหายใจยาว มันไม่ได้โกรธ\\nผมอยากให้มันโกรธบ้าง']);")
sub("await say(['เราเลยไปนั่งที่หน้าต่างแทน\\nผมบรรยายถนนให้มันฟัง มันทำเป็นสนใจ','เด็กนักเรียนเดินกลับบ้าน ร้านบะหมี่เปิดไฟ\\nหมาสีน้ำตาลตัวหนึ่งเดินผ่าน เจ้าดำกระดิกหางให้หนึ่งที','โลกอยู่ต่ำลงไปสี่ชั้น\\nใกล้พอจะมองเห็น ไกลพอจะไม่ต้องทักทายใคร']);",
    "await say(['เราไปนั่งที่หน้าต่าง ผมบรรยายถนนให้มันฟัง มันทำเป็นสนใจ\\nโลกอยู่ต่ำลงไปสี่ชั้น ใกล้พอจะมองเห็น ไกลพอจะไม่ต้องทักทายใคร']);")
sub("await say(['มื้อเย็น','ผมวางชามสองใบ ตะเกียบสองคู่\\nคืนนี้อาเหมยเข้าเวร ผมรู้ แต่มือก็วางไปแล้ว','ปีหนึ่งเก้าแปดแปด ผมได้กลับชิงเต่าครั้งแรก\\nช้าไปเก้าปี ชาวบ้านเล่าว่าแม่วางชามเผื่อผมทุกคืน สามสิบเอ็ดปี','ผมเลยวางเผื่อบ้าง\\nคนที่ยังกลับมาได้ ควรมีชามรออยู่']);",
    "await say(['มื้อเย็น ผมวางชามสองใบ ตะเกียบสองคู่\\nคืนนี้อาเหมยเข้าเวร ผมรู้ แต่มือก็วางไปแล้ว','ปีหนึ่งเก้าแปดแปด ผมได้กลับชิงเต่าครั้งแรก ช้าไปเก้าปี\\nชาวบ้านเล่าว่าแม่วางชามเผื่อผมทุกคืน สามสิบเอ็ดปี ผมเลยวางเผื่อบ้าง']);")
